# cobol_utils — MCP server generated by mcp-forge
# Provides utility functions for prime checking, factorial calculation, and string reversal extracted from the cobol codebase.
#
# Auto-generated — edit as needed.
# IMPORTANT : ce serveur compile puis exécute des sous-programmes COBOL
#             via GnuCOBOL (cobc). Assurez-vous que 'cobc' est installé et
#             accessible dans votre PATH.
#             Seuls les sous-programmes COBOL MODERNES — isolés, avec des
#             paramètres et une sortie explicites via la clause USING
#             (ex: `PROCEDURE DIVISION USING LS-N LS-RESULT.`) — sont
#             réellement exécutables. Un paragraphe/section d'un
#             PROCEDURE DIVISION monolithique (style COBOL historique,
#             état partagé en WORKING-STORAGE, aucune isolation) renvoie
#             une erreur explicite plutôt que de prétendre fonctionner.
# To run: python server.py
# To test: mcp dev server.py

from __future__ import annotations

import os
import shutil
import subprocess
import tempfile
from contextvars import ContextVar

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("cobol_utils")

_request_token: ContextVar[str] = ContextVar("_request_token", default="")

COBOL_SOURCE_DIR = os.environ.get("COBOL_SOURCE_DIR", os.path.join(os.path.dirname(os.path.abspath(__file__)), "source"))


def _cobc_available() -> bool:
    return shutil.which("cobc") is not None


def _cobc_env() -> dict:
    """Construit l'environnement du sous-processus cobc.

    Sur Windows, GnuCOBOL installé via MSYS2/MinGW (la distribution Windows
    la plus courante) a un bug connu : le compilateur résout son propre
    répertoire de config via un chemin style Unix compilé en dur
    ("/mingw64/share/gnucobol/config"), invalide dès qu'on l'exécute hors
    d'un shell MSYS2 — erreur "configuration error", peu importe le shell
    appelant (bash, PowerShell...), testé directement. Contournement
    générique (pas un chemin arbitraire propre à une machine) : dérive le
    répertoire de config relativement à l'emplacement RÉEL de cobc.exe sur
    CETTE machine (toujours "<dossier bin>/../share/gnucobol/config" dans
    cette distribution), sans écraser une config déjà fonctionnelle.
    """
    env = os.environ.copy()
    if os.name == "nt" and "COB_CONFIG_DIR" not in env:
        cobc_path = shutil.which("cobc")
        if cobc_path:
            candidate = os.path.join(os.path.dirname(cobc_path), "..", "share", "gnucobol", "config")
            if os.path.isdir(candidate):
                env["COB_CONFIG_DIR"] = candidate
    return env


def _run_cobol_driver(script_file: str, driver_lines: list[str], numeric_output: bool, source_format: str) -> str:
    """Compile `driver_lines` (un programme COBOL complet, PROGRAM-ID
    MCPFORGEDRIVER) concaténé AVANT le fichier source original, puis
    exécute le binaire obtenu.

    L'ordre (driver D'ABORD) est nécessaire : `cobc -x` désigne le PREMIER
    PROGRAM-ID du fichier comme point d'entrée de l'exécutable — testé.

    Le driver est toujours écrit en format LIBRE (`>>SOURCE FORMAT FREE`) :
    un littéral VALUE construit depuis un argument fourni à l'exécution
    (ex: une chaîne longue) peut dépasser la colonne 72, limite stricte du
    format fixe historique — testé, lève "continuation character expected"
    sinon. Le fichier source original garde son propre format détecté
    (`>>SOURCE FORMAT FIXED/FREE` au point de bascule) : GnuCOBOL permet de
    mélanger les deux formats dans un même fichier via ces directives —
    testé.
    """
    if not _cobc_available():
        return "Erreur : compilateur 'cobc' introuvable dans le PATH."

    source_path = os.path.join(COBOL_SOURCE_DIR, script_file)
    try:
        with open(source_path, encoding="utf-8") as f:
            source_code = f.read()
    except OSError as exc:
        return f"Erreur : impossible de lire {source_path} ({exc})"

    driver = (
        "      >>SOURCE FORMAT FREE\n"
        + "\n".join(driver_lines)
        + "\n      >>SOURCE FORMAT " + source_format.upper() + "\n"
        + source_code
    )

    tmp_src = None
    tmp_bin = None
    run_result = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w", suffix=".cob", delete=False, encoding="utf-8"
        ) as tmp:
            tmp.write(driver)
            tmp_src = tmp.name
        # splitext, pas une concatenation brute : GnuCOBOL 3.2 dérive en
        # réalité le nom du binaire en retirant la sous-chaîne ".cob" du nom
        # de SORTIE demandé (pas seulement de la source), pas uniquement
        # son extension — "tmp123.cob.exe" devient silencieusement
        # "tmp123.exe" en sortie réelle (testé : `-o` échoué silencieusement,
        # returncode 0, mais le fichier demandé n'existe jamais).
        tmp_bin = os.path.splitext(tmp_src)[0] + (".exe" if os.name == "nt" else ".out")

        compile_result = subprocess.run(
            ["cobc", "-x", tmp_src, "-o", tmp_bin],
            capture_output=True, text=True, timeout=30,
            env=_cobc_env(),
            shell=(os.name == "nt"),
        )
        if compile_result.returncode != 0:
            return f"Erreur de compilation COBOL : {compile_result.stderr.strip() or compile_result.stdout.strip()}"

        run_result = subprocess.run(
            [tmp_bin],
            capture_output=True, text=True, timeout=10,
            shell=(os.name == "nt"),
        )
    except subprocess.TimeoutExpired as exc:
        return f"Erreur COBOL : timeout ({exc})"
    finally:
        for _p in (tmp_src, tmp_bin):
            if _p:
                try:
                    os.unlink(_p)
                except OSError:
                    pass

    if run_result is None:
        return "Erreur COBOL : exécution jamais lancée."
    if run_result.returncode != 0:
        return f"Erreur COBOL : {run_result.stderr.strip() or run_result.stdout.strip()}"
    output = run_result.stdout.strip()
    if numeric_output:
        # PIC 9(n) s'affiche avec des zéros de tête (ex: "000000120") —
        # sans intérêt pour l'appelant, qui attend la valeur numérique.
        try:
            return str(int(output))
        except ValueError:
            pass
    return output


def _cobol_numeric_literal(value: object) -> str:
    return str(int(value))


def _cobol_string_literal(value: object, max_len: int) -> str:
    """Construit un littéral COBOL `"..."` valide pour un champ PIC X(n) :
    tronque à `max_len` (un littéral VALUE plus long que le champ cible est
    une erreur de compilation) et double les guillemets internes (seule
    règle d'échappement COBOL pour une chaîne entre guillemets doubles)."""
    text = str(value)[:max_len]
    return '"' + text.replace('"', '""') + '"'


@mcp.tool(name="check_is_prime")
def check_is_prime(
    n: int,
) -> str:
    """Tests if a given non-negative integer is a prime number. Use this to determine primality for mathematical or algorithmic tasks.
    Args:
        n: The integer to test for primality (must be between 0 and 9999).
    Returns:
        Résultat du sous-programme COBOL.
    """
    _driver_lines = [
        "       IDENTIFICATION DIVISION.",
        "       PROGRAM-ID. MCPFORGEDRIVER.",
        "       DATA DIVISION.",
        "       WORKING-STORAGE SECTION.",
        "       01 LS-N   PIC 9(4) VALUE " + _cobol_numeric_literal(n) + ".",
        "       01 LS-RESULT   PIC 9.",
        "       PROCEDURE DIVISION.",
        "           CALL \"IS-PRIME\" USING LS-N LS-RESULT",
        "           DISPLAY LS-RESULT",
        "           STOP RUN.",
    ]
    return _run_cobol_driver(
        "UTILS.CBL", _driver_lines,
        numeric_output=True,
        source_format="fixed",
    )

@mcp.tool(name="compute_factorial")
def compute_factorial(
    n2: int,
) -> str:
    """Calculates the factorial of a non-negative integer. Use this to compute the product of all positive integers up to the specified value.
    Args:
        n2: The integer for which to compute the factorial (must be between 0 and 9999).
    Returns:
        Résultat du sous-programme COBOL.
    """
    _driver_lines = [
        "       IDENTIFICATION DIVISION.",
        "       PROGRAM-ID. MCPFORGEDRIVER.",
        "       DATA DIVISION.",
        "       WORKING-STORAGE SECTION.",
        "       01 LS-N2   PIC 9(4) VALUE " + _cobol_numeric_literal(n2) + ".",
        "       01 LS-RESULT2   PIC 9(9).",
        "       PROCEDURE DIVISION.",
        "           CALL \"FACTORIAL\" USING LS-N2 LS-RESULT2",
        "           DISPLAY LS-RESULT2",
        "           STOP RUN.",
    ]
    return _run_cobol_driver(
        "UTILS.CBL", _driver_lines,
        numeric_output=True,
        source_format="fixed",
    )

@mcp.tool(name="reverse_string")
def reverse_string(
    s: str,
) -> str:
    """Reverses the character order of a given string. Use this to mirror text sequences for processing or display purposes.
    Args:
        s: The string to reverse (maximum length 50 characters).
    Returns:
        Résultat du sous-programme COBOL.
    """
    _driver_lines = [
        "       IDENTIFICATION DIVISION.",
        "       PROGRAM-ID. MCPFORGEDRIVER.",
        "       DATA DIVISION.",
        "       WORKING-STORAGE SECTION.",
        "       01 LS-S   PIC X(50) VALUE " + _cobol_string_literal(s, 50) + ".",
        "       01 LS-R   PIC X(50).",
        "       PROCEDURE DIVISION.",
        "           CALL \"REVERSE-STRING\" USING LS-S LS-R",
        "           DISPLAY LS-R",
        "           STOP RUN.",
    ]
    return _run_cobol_driver(
        "UTILS.CBL", _driver_lines,
        numeric_output=False,
        source_format="fixed",
    )


